CREATE TABLE IF NOT EXISTS rag_documents (doc_id TEXT NOT NULL UNIQUE, requested_url TEXT NOT NULL, canonical_url TEXT NOT NULL, title TEXT, category TEXT NOT NULL, source_last_updated TEXT, source_content_hash TEXT, document_version TEXT, status TEXT NOT NULL, http_status INTEGER, error_message TEXT, consecutive_404_count INTEGER NOT NULL, retrieved_at TEXT, last_success_at TEXT, last_run_at TEXT, removed_at TEXT, source_origins TEXT, indexed_content_hash TEXT, indexed_source_last_updated TEXT, last_run_action TEXT, chunked_content_hash TEXT, chunked_source_last_updated TEXT, chunked_document_version TEXT);
CREATE TABLE IF NOT EXISTS rag_chunks (chunk_id TEXT NOT NULL, doc_id TEXT NOT NULL, document_version TEXT NOT NULL, position INTEGER NOT NULL, chunk_text TEXT NOT NULL, heading_path TEXT, source_url TEXT NOT NULL, source_title TEXT NOT NULL, embedding_model TEXT, embedding_dimension INTEGER, embedding_created_at TEXT);
CREATE TABLE IF NOT EXISTS rag_index_snapshots (snapshot_id TEXT NOT NULL, embedding_model TEXT NOT NULL, embedding_dimension INTEGER NOT NULL, chunk_count INTEGER NOT NULL, artifact_path TEXT NOT NULL, chunk_map_path TEXT NOT NULL, source_snapshot_at TEXT, created_at TEXT NOT NULL, status TEXT NOT NULL, active INTEGER NOT NULL, validation_error TEXT, corpus_fingerprint TEXT, embedding_revision TEXT NOT NULL DEFAULT 'v1', chunking_revision TEXT NOT NULL DEFAULT 'v1');
CREATE TABLE IF NOT EXISTS rag_chunk_embeddings (chunk_id TEXT NOT NULL, embedding_model TEXT NOT NULL, embedding_revision TEXT NOT NULL, embedding_dimension INTEGER NOT NULL, vector TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(chunk_id, embedding_model, embedding_revision));
CREATE TABLE IF NOT EXISTS rag_evaluations (evaluation_id TEXT NOT NULL, snapshot_id TEXT NOT NULL, question TEXT NOT NULL, expected_source_url TEXT, retrieved_chunk_ids TEXT, recall_at_k REAL, source_correct INTEGER, evaluator_notes TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rag_feedback (feedback_id TEXT NOT NULL, question TEXT NOT NULL, submitted_at TEXT NOT NULL, provider TEXT NOT NULL, model TEXT, snapshot_id TEXT NOT NULL, retrieved_chunk_ids TEXT, latency_ms INTEGER, rating TEXT, comment TEXT);
CREATE TABLE IF NOT EXISTS rag_conversations (conversation_id TEXT NOT NULL, owner_user_id TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS rag_conversation_turns (turn_id TEXT NOT NULL, conversation_id TEXT NOT NULL, turn_number INTEGER NOT NULL, user_question TEXT NOT NULL, resolved_query TEXT NOT NULL, answer_text TEXT NOT NULL, supported INTEGER NOT NULL, provider TEXT NOT NULL, model TEXT, snapshot_id TEXT NOT NULL, citation_chunk_ids TEXT, citations_json TEXT, created_at TEXT NOT NULL, latency_ms INTEGER);
CREATE TABLE IF NOT EXISTS rag_retrieval_traces (trace_id TEXT NOT NULL, turn_id TEXT NOT NULL, search_number INTEGER NOT NULL, search_query TEXT NOT NULL, retrieved_chunk_ids TEXT, selected_chunk_ids TEXT, agent_decision TEXT NOT NULL, created_at TEXT NOT NULL, latency_ms INTEGER);
CREATE TABLE IF NOT EXISTS rag_request_traces (trace_id TEXT NOT NULL, turn_id TEXT, conversation_id TEXT, owner_user_id TEXT, user_question TEXT NOT NULL, resolved_query TEXT NOT NULL, retrieval_queries TEXT, retrieval_status TEXT, selected_evidence_json TEXT, raw_model_output TEXT, parsed_citation_labels TEXT, fallback_reason TEXT, final_answer_text TEXT NOT NULL, supported INTEGER NOT NULL, provider TEXT NOT NULL, model TEXT, snapshot_id TEXT NOT NULL, latency_ms INTEGER, created_at TEXT NOT NULL);
